function vSet(){
  const st=S.settings;
  $('m').innerHTML='<h2>設定</h2><div class="card"><h3>報告書の書式（Googleスプレッドシート）</h3><p class="muted">書式のスプレッドシートを開き、アドレスバーのURLを貼り付けてください。報告書は、この書式をコピーして作ります（書式そのものは変わりません）。他社の書式は、このシステムの中だけで使います。</p>'+
    S.templates.map(t=>'<label>'+esc(t.name)+'<input data-st="tpl_'+t.key+'" value="'+esc(st['tpl_'+t.key]||'')+'" placeholder="https://docs.google.com/spreadsheets/d/…"></label>'+
      '<label>写真の並び順<select data-st="order_'+t.key+'">'+[['row','横に進む（1枚目の右に2枚目、端まで行ったら次の段）'],['col','縦に進む（左の列を上から下へ、埋まったら右の列の一番上へ）'],['pair','2列ずつ横に進む（左右2枚ずつ、下の段へ）']].map(([v,l])=>'<option value="'+v+'"'+((st['order_'+t.key]||t.defaultOrder)===v?' selected':'')+'>'+l+'</option>').join('')+'</select></label>').join('')+
    '<h3>お知らせの書式</h3>'+Object.keys(NTK).map(k=>'<label>'+esc(NTK[k])+'<input data-st="tpl_nt_'+k+'" value="'+esc(st['tpl_nt_'+k]||'')+'" placeholder="https://docs.google.com/spreadsheets/d/…"></label>').join('')+'<label>お知らせの電話番号<input data-st="tel" value="'+esc(st.tel||'080-5877-7931')+'"></label>'+
    '<h3>freee（見積書の下書き）</h3><div id="frbox"><p class="muted">読み込み中…</p></div>'+
    '<h3>点検予定の通知（メール）</h3><p class="muted">毎朝7時に確認し、次回の予定日が近づくとメールで知らせます（日数前・7日前・期限切れの3回）。次回の予定日は「前回の点検日＋物件ごとの周期」です。</p><div class="g2"><label>何日前から知らせるか<select data-st="notifyDays">'+['14','30','45','60'].map(o=>'<option'+((st.notifyDays||'30')===o?' selected':'')+'>'+o+'</option>').join('')+'</select></label><label>送り先メール（空ならこのGoogleアカウント）<input data-st="notifyEmail" type="email" value="'+esc(st.notifyEmail||'')+'"></label></div>'+
    '<h3>貯水槽清掃の報告書に載せる許可証</h3><p class="muted">「自社書式：貯水槽清掃・給水設備点検報告書」の最後のページに、貯水槽清掃作業監督者の許可証を載せます。</p><label>許可証を<select data-st="lic_on"><option value="1"'+(String(st.lic_on)==='1'?' selected':'')+'>載せる</option><option value=""'+(String(st.lic_on)!=='1'?' selected':'')+'>載せない</option></select></label>'+(st.lic_file?'<p><img data-thumb="'+esc(st.lic_file)+'" alt="許可証" style="max-width:260px;border:1px solid #ddd;border-radius:6px"></p>':'<p class="muted">まだ登録されていません。</p>')+'<label class="btn q" style="text-align:center">許可証の画像を登録・差し替える<input id="licIn" type="file" accept="image/*" hidden></label>'+
    '<h3>いつもの点検責任者</h3><label>名前<input data-st="inspector" value="'+esc(st.inspector||'山田和矢')+'"></label><button class="btn" id="ss">保存する</button></div>';
  $('ss').onclick=async()=>{const o=Object.assign({},S.settings);$('m').querySelectorAll('[data-st]').forEach(el=>o[el.dataset.st]=el.value.trim());S.settings=await run('api_saveSettings',o);toast('保存しました')};
  $('m').querySelectorAll('[data-thumb]').forEach(async im=>{try{im.src=await run('api_photoThumb',im.dataset.thumb)}catch(e){}});
  $('licIn').onchange=async e=>{const f=e.target.files[0];e.target.value='';if(!f)return;toast('許可証を登録しています…');try{const url=await shrink(f,1800);const r=await run('api_uploadPhoto',url,'貯水槽清掃作業監督者_許可証.jpg');S.settings=await run('api_saveSettings',Object.assign({},S.settings,{lic_file:r.fileId,lic_on:'1'}));vSet();toast('許可証を登録しました')}catch(x){toast(x.message||'登録できませんでした')}};
  freeeSet();
}
/* ---------- 設定：よく使うものを上に。項目を押すと開く。変更は自動で保存 ---------- */
let stTimer=null;
function saveStSoon(){clearTimeout(stTimer);stTimer=setTimeout(async()=>{try{S.settings=await run('api_saveSettings',S.settings);toast('保存しました')}catch(e){toast('保存できませんでした')}},600)}
function stSec(id,icon,title,status,body,open){return '<details class="sset" id="'+id+'"'+(open?' open':'')+'><summary><span class="sic">'+icon+'</span><span class="stt"><b>'+title+'</b><small>'+status+'</small></span><span class="chev">›</span></summary><div class="sbody">'+body+'</div></details>'}
function vSet(){
  const st=S.settings,open=S.setOpen||{},isOn=String(st.lic_on)==='1';
  const ord=[['row','横に並べる','左から右へ。端まで行ったら次の段','1 2<br>3 4'],['col','縦に並べる','上から下へ。埋まったら右の列','1 3<br>2 4'],['pair','2枚ずつ','左右2枚ずつ、下の段へ','1 2<br>3 4<br><small>2列ずつ</small>']];
  const tplN=S.templates.filter(t=>st['tpl_'+t.key]).length,ntN=Object.keys(NTK).filter(k=>st['tpl_nt_'+k]).length;
  const tplBody='<p class="muted">報告書は、ここに登録した書式（Googleスプレッドシート）をコピーして作ります。書式そのものは書き換わりません。ふだんは触らなくて大丈夫です。</p>'+
    S.templates.map(t=>{const u=st['tpl_'+t.key]||'',o=st['order_'+t.key]||t.defaultOrder||'row';
      return '<div class="tplc"><div class="row" style="justify-content:space-between"><b>'+esc(t.name.replace(/：/,' ／ '))+'</b>'+(u?'<span class="pill done">登録済み</span>':'<span class="pill ng">未登録</span>')+'</div>'+
        (u?'<a href="'+esc(u)+'" target="_blank">書式を開いて確認する</a>':'')+
        '<div class="slab">写真の並べ方</div><div class="ordg">'+ord.map(([v,l,d,g])=>'<label class="ordc'+(o===v?' on':'')+'"><input type="radio" name="ord_'+t.key+'" data-ord="'+t.key+'" value="'+v+'"'+(o===v?' checked':'')+'><span class="og">'+g+'</span><b>'+l+'</b><small>'+d+'</small></label>').join('')+'</div>'+
        '<details class="more"><summary>書式を別のものに差し替える</summary><p class="muted">新しい書式のスプレッドシートを開き、画面上のアドレス（https://docs.google.com/…）をコピーして貼り付けてください。</p><input data-st="tpl_'+t.key+'" value="'+esc(u)+'" placeholder="https://docs.google.com/spreadsheets/d/…"></details></div>'}).join('');
  const ntBody='<p class="muted">掲示用の告知書類の元になる書式です。ふだんは触らなくて大丈夫です。</p>'+Object.keys(NTK).map(k=>{const u=st['tpl_nt_'+k]||'';
      return '<div class="tplc"><div class="row" style="justify-content:space-between"><b>'+esc(NTK[k])+'</b>'+(u?'<span class="pill done">登録済み</span>':'<span class="pill ng">未登録</span>')+'</div>'+(u?'<a href="'+esc(u)+'" target="_blank">書式を開いて確認する</a>':'')+
        '<details class="more"><summary>書式を別のものに差し替える</summary><input data-st="tpl_nt_'+k+'" value="'+esc(u)+'" placeholder="https://docs.google.com/spreadsheets/d/…"></details></div>'}).join('');
  $('m').innerHTML='<h2>設定</h2><p class="muted" style="margin:0">変えたい項目を押すと開きます。変更は自動で保存されます。</p>'+
    stSec('s_me','👤','あなたの情報',esc(st.inspector||'山田和矢')+'　'+esc(st.tel||'080-5877-7931'),
      '<label>作業責任者の名前（報告書に入ります）<input data-st="inspector" value="'+esc(st.inspector||'山田和矢')+'"></label><label>電話番号（告知書類に入ります）<input data-st="tel" inputmode="tel" value="'+esc(st.tel||'080-5877-7931')+'"></label>',open.s_me!==false)+
    stSec('s_lic','🪪','報告書に載せる許可証',isOn&&st.lic_file?'貯水槽清掃の報告書の最後に載せています':'載せていません',
      '<label class="sw"><input type="checkbox" id="licOn"'+(isOn?' checked':'')+'><span>貯水槽清掃の報告書（自社書式）の最後のページに載せる</span></label>'+
      (st.lic_file?'<img data-thumb="'+esc(st.lic_file)+'" alt="許可証" class="licimg">':'<p class="muted">まだ画像がありません。下のボタンから登録してください。</p>')+
      '<label class="btn q" style="text-align:center">'+(st.lic_file?'画像を差し替える':'画像を登録する')+'<input id="licIn" type="file" accept="image/*" hidden></label>',!!open.s_lic)+
    stSec('s_ntf','🔔','次回点検のお知らせメール',(st.notifyDays||'30')+'日前から　'+esc(st.notifyEmail||'このGoogleアカウント')+' へ',
      '<p class="muted">次回の点検日（前回の点検日＋物件ごとの周期）が近づくと、毎朝7時にメールで知らせます。</p><label>何日前から知らせるか<select data-st="notifyDays">'+['14','30','45','60'].map(o=>'<option value="'+o+'"'+((st.notifyDays||'30')===String(o)?' selected':'')+'>'+o+'日前</option>').join('')+'</select></label><label>送り先のメール（空ならこのGoogleアカウント）<input data-st="notifyEmail" type="email" inputmode="email" value="'+esc(st.notifyEmail||'')+'"></label>',!!open.s_ntf)+
    stSec('s_tpl','📄','報告書の書式',tplN+'件 登録済み・写真の並べ方',tplBody,!!open.s_tpl)+
    stSec('s_nt','📢','告知書類の書式',ntN+'件 登録済み',ntBody,!!open.s_nt)+
    stSec('s_fr','💴','freee連携（見積書の下書き）','<span id="frst">確認中…</span>','<div id="frbox"><p class="muted">読み込み中…</p></div>',!!open.s_fr);
  const m=$('m');
  m.querySelectorAll('details.sset').forEach(d=>d.addEventListener('toggle',()=>{S.setOpen=Object.assign({},S.setOpen,{[d.id]:d.open})}));
  m.querySelectorAll('[data-st]').forEach(el=>el.addEventListener('change',()=>{S.settings[el.dataset.st]=el.value.trim();saveStSoon()}));
  m.querySelectorAll('[data-ord]').forEach(el=>el.addEventListener('change',()=>{S.settings['order_'+el.dataset.ord]=el.value;el.closest('.ordg').querySelectorAll('.ordc').forEach(c=>c.classList.toggle('on',c.contains(el)));saveStSoon()}));
  $('licOn').onchange=e=>{S.settings.lic_on=e.target.checked?'1':'';saveStSoon();setTimeout(vSet,700)};
  m.querySelectorAll('[data-thumb]').forEach(async im=>{try{im.src=await run('api_photoThumb',im.dataset.thumb)}catch(e){}});
  $('licIn').onchange=async e=>{const f=e.target.files[0];e.target.value='';if(!f)return;toast('許可証を登録しています…');try{const url=await shrink(f,1800);const r=await run('api_uploadPhoto',url,'貯水槽清掃作業監督者_許可証.jpg');S.settings=await run('api_saveSettings',Object.assign({},S.settings,{lic_file:r.fileId,lic_on:'1'}));S.setOpen=Object.assign({},S.setOpen,{s_lic:true});vSet();toast('許可証を登録しました')}catch(x){toast(x.message||'登録できませんでした')}};
  freeeSet();
}
